from h34 import *
M=mcq;F=tf;S=short;N=num
def col(x,rows,hl=None):
    return ''.join(f'<text x="{x}" y="{y}" text-anchor="middle" font-size="26">{t}</text>' for y,t in rows)
b='<text x="360" y="26" text-anchor="middle" font-size="18" font-weight="bold">Adding with regrouping: 438 + 476</text>'
b+='<text x="200" y="70" text-anchor="middle" font-size="16" fill="#555">H</text><text x="260" y="70" text-anchor="middle" font-size="16" fill="#555">T</text><text x="320" y="70" text-anchor="middle" font-size="16" fill="#555">O</text>'
b+='<text x="260" y="105" text-anchor="middle" font-size="20" fill="#d1495b">1</text><text x="200" y="105" text-anchor="middle" font-size="20" fill="#d1495b">1</text>'
b+=col(200,[(140,'4'),(180,'4'),(250,'9')])+col(260,[(140,'3'),(180,'7'),(250,'1')])+col(320,[(140,'8'),(180,'6'),(250,'4')])
b+='<text x="140" y="180" font-size="26">+</text><line x1="150" y1="200" x2="350" y2="200" stroke="#222" stroke-width="3"/>'
b+='<text x="520" y="120" text-anchor="middle" font-size="16">8 + 6 = 14 ones</text><text x="520" y="150" text-anchor="middle" font-size="16">= 1 ten + 4 ones</text><text x="520" y="190" text-anchor="middle" font-size="16">3 + 7 + 1 = 11 tens</text><text x="520" y="220" text-anchor="middle" font-size="16">= 1 hundred + 1 ten</text><text x="520" y="260" text-anchor="middle" font-size="16">4 + 4 + 1 = 9 hundreds</text>'
svgfile('c4m-clean-regroup.svg',720,290,b)
chapter(4,'maths','the-cleanest-village','The Cleanest Village',
 ('A trip to Asia’s cleanest village','Daisy and Lou study in Shillong. Their school is going on a trip to Mawlynnong, a village in Meghalaya known as Asia’s cleanest village, 79 km away. To get ready they go shopping, and on the way they add and subtract many numbers. In this chapter we learn how to add and subtract bigger numbers, with regrouping, and how to estimate first.'),
 [('The school trip poster',['The poster says the trip is to Mawlynnong, and it costs ₹500 for each child.','The village is 79 km from Shillong in the East Khasi Hills. It has 77 families and 414 people.','The bus leaves at 7 in the morning and returns at 4 in the afternoon, so the trip takes 9 hours.','Numbers on posters, price lists and tickets are all around us, and we use addition and subtraction to understand them.']),
  ('Shopping and the price list',['Daisy and Lou help Sapan Dada, who sells fruits and vegetables from a cart. The price list shows the cost of 1 kg of each item.','To find the cost of 2 kg of beans, we add the price two times, ₹95 + ₹95 = ₹190.','For 1 kg of custard apple and 1 kg of sapota we add ₹45 and ₹70, which gives ₹115.','For 2 kg of radish and 2 kg of papaya we find 23 + 23 = 46 and 65 + 65 = 130, and then 46 + 130 = 176.','We can use a number line, play money or any method we like, and compare the ways to see which is easiest.']),
  ('Finding the balance',['At Udaya Didi’s shop the children return the balance. The balance is the money left after paying the cost.','If the cost is ₹113 and the customer pays ₹150, the balance is 150 − 113 = ₹37.','We can count up from 113 to 150 on a number line, and the jumps add up to 37, so subtraction and counting up give the same answer.','The strange puzzle: each orange costs ₹21 and each child buys 2, so each pays 2 × 21 = ₹42. The balances are 50 − 42 = ₹8, 100 − 42 = ₹58, 200 − 42 = ₹158 and 500 − 42 = ₹458.']),
  ('Estimating first',['Before we add or subtract we estimate. An estimate is a quick guess that is close to the answer.','To estimate 24 + 28, think of 24 as about 20 and 28 as about 30. The sum is about 50.','Estimating helps us know whether our final answer is sensible. If we get 520 for this problem, we know it is wrong.']),
  ('Adding with regrouping',['24 teachers and 28 teachers are going on the trip. We add 24 + 28 by tens and ones.','4 ones and 8 ones make 12 ones. 10 ones make one ten, so we regroup 12 ones as 1 ten and 2 ones.','Then 2 tens + 2 tens + 1 ten = 5 tens, so the answer is 52 teachers.','Now 438 children and 476 children are going. The ones are 8 + 6 = 14, so we write 4 and regroup 10 ones as 1 ten.','The tens are 3 + 7 + 1 = 11, so we write 1 and regroup 10 tens as 1 hundred. The hundreds are 4 + 4 + 1 = 9, so 438 + 476 = 914 children.','We say regrouping and not carrying, because we are exchanging ten of one place for one of the next place.']),
  ('More adding',['Daisy and Lou bought pusaw for ₹38 and ₹16. The ones make 8 + 6 = 14, so we regroup, and the tens make 3 + 1 + 1 = 5, giving ₹54.','They collected ₹185 and their mother gave ₹125. The ones are 5 + 5 = 10, which gives 1 ten. The tens are 8 + 2 + 1 = 11, which gives 1 hundred. The hundreds are 1 + 1 + 1 = 3, so they took ₹310.','Always start adding from the ones place and move left.']),
  ('Subtracting with regrouping',['83 children bought pusaw and 46 bought fruit plates. How many more bought pusaw? We find 83 − 46.','We cannot take 6 ones from 3 ones, so we regroup 1 ten as 10 ones. Now we have 7 tens and 13 ones.','13 − 6 = 7 ones and 7 − 4 = 3 tens, so the answer is 37 children.','Subtracting 215 from 438 is easy, since no regrouping is needed: 8 − 5 = 3, 3 − 1 = 2 and 4 − 2 = 2, so 223 children are waiting.','For 310 − 179 we need to regroup twice. We regroup 1 hundred as 10 tens, and then one of those tens as 10 ones. This gives ₹131.']),
  ('Checking and quick ways',['We check subtraction by adding. 131 + 179 = 310, so the answer is right.','There are quick ways too. To do 410 − 12, take 10 away first to get 400, and then take 2 more to get 398.','To add 99, add 100 and then take 1 away. So 811 + 99 = 811 + 100 − 1 = 910.','Using friendly numbers like 10 and 100 makes calculation fast.']),
  ('Word problems',['In word problems, do not just look for key words like total or left. Picture the story and decide what happens.','If something is joined, we add. If something is taken away, or we compare two groups, we subtract.','Number pair hunt: look at the grid and choose two neighbouring numbers. To find the largest sum, we pick the two biggest neighbours.','Missing digits puzzles need us to think about regrouping, by working from the ones place.'])],
 [('There are 438 children from one school and 476 from another. How many children go on the trip?',[('We join the two groups, so we add 438 + 476.','Estimate first: about 400 + 500 = 900.'),('Ones: 8 + 6 = 14, write 4 and regroup 1 ten. Tens: 3 + 7 + 1 = 11, write 1 and regroup 1 hundred.','Regroup 10 ones to 1 ten and 10 tens to 1 hundred.'),('Hundreds: 4 + 4 + 1 = 9. So 914 children go.','The estimate 900 is close, so our answer is sensible.')]),
  ('Daisy and Lou had ₹310 and now have ₹179 left. How much have they spent?',[('We find what is taken away, so 310 − 179.','Estimate: about 300 − 180 = 120.'),('Ones: 0 is less than 9, so regroup a ten. But the tens place is 1, so regroup 1 hundred into 10 tens first.','Regroup twice.'),('After regrouping: 10 − 9 = 1 one, 10 − 7 = 3 tens, 2 − 1 = 1 hundred. So they spent ₹131.','Check: 131 + 179 = 310.')])],
 ('Explain how to add and subtract 3-digit numbers with regrouping.',['Start from the ones place and move left','In addition, regroup 10 ones as 1 ten and 10 tens as 1 hundred','In subtraction, regroup 1 ten as 10 ones when ones are not enough','Estimate first and check the answer'],['Start from the hundreds place','Always add the smaller number to the bigger one in subtraction','We never need to estimate or check']),
 ['We estimate first, then work out the exact answer.','To add with regrouping, make a new ten from 10 ones and a new hundred from 10 tens.','To subtract, regroup a ten into 10 ones, or a hundred into 10 tens, when needed.','Check subtraction by adding.','Friendly numbers like 10 and 100 give quick ways of adding and subtracting.'],
 [M('1',1,'How much is 24 + 28?','52',[('42','Add the ones 4 + 8 = 12 and regroup, so tens become 5'),('412','We cannot write 2 and 4 side by side; we regroup')],'Add ones and regroup.'),
  M('2',1,'What do we call the money returned after paying more than the cost?','Balance',[('Estimate','An estimate is a close guess'),('Price','Price is what something costs')],'Balance = money paid − cost.'),
  M('3',1,'Where do we start when adding two numbers in columns?','Ones place',[('Hundreds place','We start from the right, with ones'),('Tens place','We begin with ones, then tens')],'Ones first, then tens, then hundreds.'),
  M('4',1,'What is 83 − 46?','37',[('47','7 tens and 13 ones, 13 − 6 = 7 and 7 − 4 = 3, so 37'),('43','We cannot just subtract the smaller digit from the larger in each place')],'We regroup 1 ten into 10 ones.'),
  M('5',2,'What is 438 + 476?','914',[('804','You may have forgotten to add the regrouped ten or hundred'),('814','The hundreds are 4 + 4 + 1 = 9, not 8')],'Ones 14, tens 11, hundreds 9.'),
  M('6',2,'What is 310 − 179?','131',[('231','We have to regroup 2 times, check the hundreds again'),('141','The tens become 3 after regrouping')],'131 + 179 = 310.'),
  M('7',2,'Which is the best estimate for 438 + 476?','About 900',[('About 500','That is far too small'),('About 1400','That is far too big')],'400 + 500 = 900.'),
  M('8',2,'Each orange costs ₹21 and a child buys 2 and pays ₹100. What is the balance?','₹58',[('₹42','That is the cost of 2 oranges'),('₹79','That is 100 − 21, for only 1 orange')],'2 × 21 = 42, and 100 − 42 = 58.'),
  N('9',2,'Radish ₹23 per kg and papaya ₹65 per kg. What is the cost of 2 kg of each?',176,'46 + 130 = 176.',[(88,'That is for 1 kg of each'),(130,'That is only the papaya')],'rupees'),
  M('10',2,'How can we quickly find 811 + 99?','Add 100 and take away 1',[('Add 10 and take away 1','99 is 1 less than 100, not 10'),('Subtract 100','We are adding, not subtracting')],'811 + 100 = 911, minus 1 = 910.'),
  F('11',2,'We can check a subtraction by adding the answer to the number we took away.',True,'131 + 179 = 310.'),
  F('12',3,'In subtraction, if the ones digit on top is smaller, we regroup 1 ten as 10 ones.',True,'This gives us enough ones.')],
 svgs=[('c4m-clean-regroup','A column addition 438 + 476 showing regrouping with 1 ten and 1 hundred carried over.','Ones 14, tens 11, hundreds 9, so the sum is 914.')],
 keep=['estimate','regrouping','balance'])
